#include <iostream>
using namespace std;
int find(int A[], int n, int key) { A[n] = key; int i = 0; while (A[i] != key) i++; return i < n ? i : -1; }
int main() { int A[6] = {4, 8, 15, 16, 23}; cout << find(A, 5, 16) << " " << find(A, 5, 42) << endl; }

#include <iostream>
