int main() {
    int A[8] = {1, 3, 5, 7, 9, 11, 13, 15};
    int L = 0, R = 7, key = 11;
    while (L <= R) {
        int mid = L + (R - L) / 2;
        cout << mid << " ";
        if (A[mid] == key) { cout << "found " << mid << endl; break; }
        if (A[mid] < key) L = mid + 1; else R = mid - 1;
    }
}

