#include <iostream>
using namespace std;
int daysIn(int m, int y) {
    if (m == 2) return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 ? 29 : 28;
    if (m == 4 || m == 6 || m == 9 || m == 11) return 30;
    return 31;
}
void nextDay(int& d, int& m, int& y) {
    if (++d > daysIn(m, y)) { d = 1; if (++m > 12) { m = 1; y++; } }
}
void show(int d, int m, int y) { nextDay(d, m, y); cout << d << "/" << m << "/" << y; }
int main() { show(28, 2, 2024); cout << " "; show(28, 2, 2023); cout << " "; show(31, 12, 2023); cout << endl; }

#include <iostream>
#include <algorithm>
using namespace std;
string add(string a, string b) {
    string r; int i = a.size() - 1, j = b.size() - 1, c = 0;
    while (i >= 0 || j >= 0) {
        int s = c;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        r += char('0' + s % 10);
        c = s / 10;
    }
    if (c) r += char('0' + c);
    reverse(r.begin(), r.end());
    return r;
}
int main() { cout << add("999", "99") << " " << add("5", "5") << endl; }

