int main() {
    int n = 3, a[3][3] = {}, r = 0, c = n / 2;
    for (int k = 1; k <= n * n; k++) {
        a[r][c] = k;
        int nr = (r - 1 + n) % n, nc = (c + 1) % n;
        if (a[nr][nc]) { nr = (r + 1) % n; nc = c; }
        r = nr; c = nc;
    }
    for (int i = 0; i < n; i++) { for (int j = 0; j < n; j++) cout << a[i][j] << (j + 1 < n ? " " : ""); cout << endl; }
}

#include <iostream>
using namespace std;
int main() {
    string g[3] = {"*...", "....", "..*."};
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 4; j++) {
            if (g[i][j] == '*') { cout << '*'; continue; }
            int c = 0;
            for (int di = -1; di <= 1; di++)
                for (int dj = -1; dj <= 1; dj++) {
                    int x = i + di, y = j + dj;
                    if (x >= 0 && x < 3 && y >= 0 && y < 4 && g[x][y] == '*') c++;
                }
            cout << c;
        }
        cout << endl;
    }
}

