#include <iostream>
#include <algorithm>
using namespace std;
int goi = 0;
int maxRec(int A[], int l, int r) {
    goi++;
    if (l == r) return A[l];
    int m = (l + r) / 2;
    return max(maxRec(A, l, m), maxRec(A, m + 1, r));
}
int main() { int A[8] = {3, 9, 2, 7, 5, 1, 8, 4}; int v = maxRec(A, 0, 7); cout << v << " " << goi << endl; }

